import heapq
from typing import List

class Solution:
    def findMaxSum(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        n = len(nums1)
        order = sorted(range(n), key=lambda i: nums1[i])
        answer = [0] * n
        heap = []
        cur_sum = 0
        i = 0
        while i < n:
            j = i
            while j < n and nums1[order[j]] == nums1[order[i]]:
                j += 1
            # All indices order[i..j-1] share same nums1 value; their answer uses heap state before adding them
            for t in range(i, j):
                answer[order[t]] = cur_sum
            for t in range(i, j):
                idx = order[t]
                v = nums2[idx]
                if len(heap) < k:
                    heapq.heappush(heap, v)
                    cur_sum += v
                else:
                    if v > heap[0]:
                        cur_sum += v - heap[0]
                        heapq.heapreplace(heap, v)
            i = j
        return answer

import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    a = [int(x) for x in data[1:1+n]]

    lo, hi = 0, n // 2
    while lo < hi:
        mid = (lo + hi + 1) // 2
        # pair smallest mid with largest mid
        ok = True
        for i in range(mid):
            if 2 * a[i] > a[n - mid + i]:
                ok = False
                break
        if ok:
            lo = mid
        else:
            hi = mid - 1
    print(lo)

