from typing import List
from collections import defaultdict

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        NEG_INF = -10**30

        best_no_delete = NEG_INF
        cur_no_delete = NEG_INF

        # dp[x] = best subarray sum ending here after deleting all x's,
        # for negative values x that have appeared in the current useful state.
        dp = {}
        ans = NEG_INF

        for a in nums:
            if cur_no_delete == NEG_INF:
                cur_no_delete = a
            else:
                cur_no_delete = max(a, cur_no_delete + a)
            best_no_delete = max(best_no_delete, cur_no_delete)
            ans = max(ans, best_no_delete)

            if a < 0:
                # Start using deletion value a here, deleting this element from an
                # existing non-empty subarray ending before it.
                prev = dp.get(a, NEG_INF)
                dp[a] = max(prev, cur_no_delete - a)
            else:
                # Positive/zero values extend every deletion-state subarray.
                remove = []
                for x, s in dp.items():
                    ns = s + a
                    dp[x] = ns
                    ans = max(ans, ns)
                    # States with non-positive sum are never better than starting fresh
                    # later from the normal Kadane state.
                    if ns <= 0:
                        remove.append(x)
                for x in remove:
                    del dp[x]

            if a < 0 and a in dp:
                ans = max(ans, dp[a])

        return ans

import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    idx = 0
    n = data[idx]
    idx += 1

    dice = []
    for _ in range(n):
        k = data[idx]
        idx += 1
        freq = {}
        for _ in range(k):
            a = data[idx]
            idx += 1
            freq[a] = freq.get(a, 0) + 1
        dice.append((k, freq))

    ans = 0.0

    for i in range(n):
        ki, fi = dice[i]
        for j in range(i + 1, n):
            kj, fj = dice[j]

            if len(fi) <= len(fj):
                small, large = fi, fj
            else:
                small, large = fj, fi

            same = 0
            for value, count in small.items():
                same += count * large.get(value, 0)

            ans = max(ans, same / (ki * kj))

    print(f"{ans:.15f}")

if __name__ == "__main__":
    main()

import sys

def main():
    input = sys.stdin.readline
    N = int(input())
    P = list(map(int, input().split()))

    bit = [0] * (N + 1)

    def add(i, x):
        while i <= N:
            bit[i] += x
            i += i & -i

    def kth(k):
        idx = 0
        step = 1 << (N.bit_length() - 1)
        while step:
            nxt = idx + step
            if nxt <= N and bit[nxt] < k:
                idx = nxt
                k -= bit[nxt]
            step >>= 1
        return idx + 1

    for i in range(1, N + 1):
        add(i, 1)

    ans = [0] * N

    for value in range(N, 0, -1):
        pos = kth(P[value - 1])
        ans[pos - 1] = value
        add(pos, -1)

    print(*ans)

if __name__ == "__main__":
    main()

import sys

def solve():
    # Read all tokens from standard input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    idx = 1

    dice = []
    # Parse the input for each die
    for _ in range(N):
        K = int(input_data[idx])
        idx += 1
        freq = {}
        for _ in range(K):
            val = int(input_data[idx])
            if val in freq:
                freq[val] += 1
            else:
                freq[val] = 1
            idx += 1
        dice.append((K, freq))

    max_num = 0
    max_den = 1

    # Compare all pairs of dice
    for i in range(N):
        K_i, freq_i = dice[i]
        for j in range(i + 1, N):
            K_j, freq_j = dice[j]

            # To optimize the inner loop, iterate over the die with fewer unique faces
            if len(freq_i) > len(freq_j):
                freq_a, freq_b = freq_j, freq_i
            else:
                freq_a, freq_b = freq_i, freq_j

            match_ways = 0
            for val, count in freq_a.items():
                if val in freq_b:
                    match_ways += count * freq_b[val]

            den = K_i * K_j
            num = match_ways

            # Compare fractions exactly using cross-multiplication to avoid float precision issues
            if num * max_den > max_num * den:
                max_num = num
                max_den = den

    # Python's float division provides sufficient precision for the maximum fraction
    print(f"{max_num / max_den:.15f}")

if __name__ == '__main__':
    solve()
